// ChefAtHome / Pajti Imre — client-side i18n.
// Hungarian ("hu") is the default copy baked directly into index.html.
// Every other language swaps in from the I18N table above.
(function () {
  var ORIG = null;
  function capture() {
    ORIG = { text: {}, ph: {} };
    document.querySelectorAll('[data-i18n]').forEach(function (el) {
      ORIG.text[el.getAttribute('data-i18n')] = el.textContent;
    });
    document.querySelectorAll('[data-i18n-ph]').forEach(function (el) {
      ORIG.ph[el.getAttribute('data-i18n-ph')] = el.getAttribute('placeholder') || '';
    });
  }
  window.setLang = function (lang) {
    if (!ORIG) capture();
    var dict = I18N[lang] || null; // null => Hungarian original
    document.querySelectorAll('[data-i18n]').forEach(function (el) {
      var k = el.getAttribute('data-i18n');
      var v = dict ? (dict[k] != null ? dict[k] : ORIG.text[k]) : ORIG.text[k];
      if (v != null && el.textContent !== v) el.textContent = v;
    });
    document.querySelectorAll('[data-i18n-ph]').forEach(function (el) {
      var k = el.getAttribute('data-i18n-ph');
      var v = dict ? (dict['ph.' + k] != null ? dict['ph.' + k] : ORIG.ph[k]) : ORIG.ph[k];
      if (v != null) el.setAttribute('placeholder', v);
    });
    document.documentElement.lang = lang;
    try { localStorage.setItem('pi_lang', lang); } catch (e) {}
    var sel = document.getElementById('langSelect');
    if (sel && sel.value !== lang) sel.value = lang;
  };
  document.addEventListener('DOMContentLoaded', function () {
    capture();
    var saved = null;
    try { saved = localStorage.getItem('pi_lang'); } catch (e) {}
    var lang = saved;
    if (!lang) {
      var nav = (navigator.language || 'en').toLowerCase();
      lang = nav.slice(0, 2);
      if (lang === 'nb' || lang === 'nn' || nav.indexOf('no') === 0) lang = 'no';
    }
    if (lang !== 'hu' && !I18N[lang]) lang = 'en';
    window.setLang(lang);

  });
})();
